window.CubeApiDocs.define("api-Psychology-检测图像是否是绘画",{"id":"api-Psychology-检测图像是否是绘画","versions":[{"version":"1.0.0","toc":[{"id":"overview","title":"用途与调用说明"},{"id":"request-example","title":"请求示例"},{"id":"parameters","title":"路径与通用参数"},{"id":"body","title":"请求体参数"},{"id":"success","title":"成功响应"},{"id":"errors","title":"错误与处理"}],"html":"\u003carticle data-api-id=\"api-Psychology-检测图像是否是绘画\">\u003cheader class=\"article-header\">\u003cp class=\"eyebrow\">心理学服务 · v1.0.0\u003c/p>\u003ch1 tabindex=\"-1\">检测图像是否是绘画\u003c/h1>\u003cdiv class=\"endpoint\">\u003cspan class=\"method post\">POST\u003c/span>\u003ccode>/aigc/psychology/check/:token\u003c/code>\u003cbutton type=\"button\" data-copy=\"path\" aria-label=\"复制接口路径\">复制路径\u003c/button>\u003c/div>\u003c/header>\u003csection class=\"doc-section\" id=\"overview\">\u003ch2>用途与调用说明\u003c/h2>\u003cp>检测图像是否是绘画。该检测接口通过计算机视觉技术检测图像，用于预检测用户上传的图像数据是否符合绘画图像要求，排除用户上传了其他照片或者空白绘画等情况。 \u003cbr/>需要注意的是该接口并不能绝对准确检测出图像是否符合绘画要求。\u003c/p>\u003c/section>\u003csection class=\"doc-section\" id=\"request-example\">\u003ch2>请求示例\u003c/h2>\u003cdiv class=\"example\">\u003ch3>请求示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"fileCode\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"qxplztvpmoyuZatmTRmoPMfHOGKuNPWnEGRNMDgzmHVuWySNYxZRHhHYrSMcuNLq\"\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"parameters\">\u003ch2>路径与通用参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Parameter\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>token\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>授权令牌。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"body\">\u003ch2>请求体参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"字段说明\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>fileCode\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>文件码。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"success\">\u003ch2>成功响应\u003c/h2>\u003cdiv class=\"example\">\u003ch3>应答示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>HTTP/\u003cspan class=\"token number\">1.1\u003c/span> \u003cspan class=\"token number\">200\u003c/span> OK\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"result\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token boolean\">true\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Success 200\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>result\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Boolean\u003c/code>\u003c/td>\u003ctd>\u003cp>文件是否是绘画图像。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"errors\">\u003ch2>错误与处理\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Error 4xx\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>400\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>参数错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>401\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>令牌错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>404\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>提交请求错误。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003c/article>"}]});
